<?php
declare(strict_types=1);
require_once __DIR__ . '/business/config/role_security_alerts.php';

$error=null;$success=null;$user=null;$alerts=[];$status=[];$csrf='';$openCount=0;
try{
    $pdo=role_portal_db();role_security_ensure($pdo);security_step17_session_start();
    $user=security_step17_session_user($pdo,true);
    if(!$user){header('Location: login.php');exit;}
    if((int)($user['must_change_password']??0)===1){header('Location: change_password.php?required=1');exit;}
    $ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$csrf=security_step17_csrf();
    if($_SERVER['REQUEST_METHOD']==='POST'){
        security_step17_verify_csrf((string)($_POST['csrf']??''));
        if((string)($_POST['action']??'')==='acknowledge'){
            role_security_acknowledge_own_alert($pdo,(int)($_POST['alert_id']??0));
            $success='Security alert acknowledged. It remains in history for audit and review.';
        }
    }
    $alerts=role_security_user_alerts($pdo,$orgId,(int)$user['id'],60);
    $status=role_security_status($pdo,$orgId,(int)$user['id']);
    $openCount=role_security_open_alert_count($pdo,$orgId,(int)$user['id']);
}catch(Throwable $e){$error=$e->getMessage();}
$home=$user?role_portal_home($user):'login.php';
function alert_label(string $v):string{return strtoupper(str_replace('_',' ',$v));}
function alert_when(?string $v):string{if(!$v)return '—';$t=strtotime($v);return $t?date('d M Y, h:i A',$t):$v;}
?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Security Alerts - Healthcare Wellness Club</title><link rel="stylesheet" href="pages/auth.css"><style>
.alert-grid{display:grid;gap:11px;margin-top:14px}.alert-card{border:1px solid #dfe8e3;border-radius:16px;padding:15px;background:#fff}.alert-card.high,.alert-card.critical{background:linear-gradient(145deg,#fff,#fff0f0);border-color:#eed0d2}.alert-card.medium{background:linear-gradient(145deg,#fff,#fff8e8)}.alert-card.info{background:linear-gradient(145deg,#fff,#eef5ff)}.alert-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.alert-head h3{margin:0;font-size:.95rem}.alert-card p{margin:7px 0 0;color:#66786e;font-size:.77rem;line-height:1.55}.alert-meta{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.alert-action{margin-top:11px}.alert-empty{padding:28px;text-align:center;color:#718078}.security-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:14px}.security-summary>div{padding:13px;border:1px solid #dfe8e3;border-radius:13px;background:rgba(255,255,255,.8)}.security-summary span{display:block;color:#738179;font-size:.67rem}.security-summary b{display:block;margin-top:5px;font-size:.9rem}@media(max-width:720px){.security-summary{grid-template-columns:1fr}.alert-head{flex-direction:column}}
</style></head><body class="auth-page"><header class="auth-top"><a class="auth-brand" href="<?=$home?>"><img src="img/logo.png" alt="Healthcare Wellness Club"><span><strong>Healthcare Wellness Club</strong><small>Security Alerts • Suspicious Login Detection</small></span></a><nav class="auth-nav"><a class="auth-btn" href="account.php">My Account</a><a class="auth-btn" href="<?=$home?>">My Portal</a><a class="auth-btn" href="logout.php">Sign Out</a></nav></header><main class="auth-shell"><section class="portal-head"><div><span class="role-badge">SECURITY</span><h1>Security Alerts</h1><p>Review unusual sign-in patterns detected for your account. Alerts do not automatically change your role or grant access.</p></div><div class="account-list" style="min-width:220px"><div class="account-row"><span>Open alerts</span><b><?=$openCount?></b></div><div class="account-row"><span>Account access</span><b><?=(int)($status['is_locked']??0)===1?'LOCKED':'ACTIVE'?></b></div></div></section><?php if($error):?><div class="auth-alert" role="alert"><?=security_step17_h($error)?></div><?php endif;?><?php if($success):?><div class="auth-alert good"><?=security_step17_h($success)?></div><?php endif;?><section class="portal-card full"><h2>Account Security Status</h2><p>Administrator controls account locking. Locking revokes active sessions immediately. New-device or failed-login alerts alone do not auto-lock your account.</p><div class="security-summary"><div><span>Status</span><b><?=(int)($status['is_locked']??0)===1?'LOCKED':'ACTIVE / UNLOCKED'?></b></div><div><span>Open security alerts</span><b><?=$openCount?></b></div><div><span>Latest lock/unlock</span><b><?=security_step17_h(alert_when((string)($status['unlocked_at']??$status['locked_at']??'')))?></b></div></div></section><section class="portal-card full" style="margin-top:14px"><h2>Alert History</h2><p>Recognize an alert only when you know the activity was yours. Acknowledged and resolved items remain in history.</p><div class="alert-grid"><?php foreach($alerts as $a):$sev=(string)$a['severity'];?><article class="alert-card <?=security_step17_h($sev)?>"><div class="alert-head"><div><h3><?=security_step17_h((string)$a['title'])?></h3><p><?=security_step17_h((string)($a['details']?:'No additional details.'))?></p></div><span class="status-pill"><?=security_step17_h(strtoupper($sev))?></span></div><div class="alert-meta"><span class="role-badge"><?=security_step17_h(alert_label((string)$a['status']))?></span><span class="role-badge"><?=security_step17_h(alert_when((string)$a['created_at']))?></span><?php if($a['ip_address']):?><span class="role-badge">IP <?=security_step17_h((string)$a['ip_address'])?></span><?php endif;?></div><?php if((string)$a['status']==='open'):?><form class="alert-action" method="post"><input type="hidden" name="csrf" value="<?=security_step17_h($csrf)?>"><input type="hidden" name="action" value="acknowledge"><input type="hidden" name="alert_id" value="<?=(int)$a['id']?>"><button class="auth-btn primary" type="submit">I Recognize This Activity</button></form><?php endif;?></article><?php endforeach;?><?php if(!$alerts):?><div class="alert-empty">No security alerts have been recorded for this account yet.</div><?php endif;?></div></section></main></body></html>
